package ai.xzkj.recruitment.localconnector;
import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;
@Entity@Table(name="local_connector_offline_drills")class LocalConnectorOfflineDrill{@Id private UUID id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="local_connector_device_id")private BrowserDevice device;@Column(name="action_type",nullable=false,length=32)private String actionType;@Column(nullable=false,length=16)private String outcome;@Column(name="evidence_source",nullable=false,length=24)private String evidenceSource;@Column(name="before_digest",nullable=false,length=64)private String beforeDigest;@Column(name="after_digest",nullable=false,length=64)private String afterDigest;@Column(name="receipt_digest",nullable=false,length=64)private String receiptDigest;@Column(name="failure_reason",length=300)private String failureReason;@Column(name="created_at",nullable=false)private Instant createdAt;protected LocalConnectorOfflineDrill(){}LocalConnectorOfflineDrill(BrowserDevice d,OfflineDrillReport r,Instant now){id=UUID.randomUUID();device=d;actionType=r.actionType();outcome=r.outcome();evidenceSource=r.evidenceSource();beforeDigest=r.beforeDigest();afterDigest=r.afterDigest();receiptDigest=r.receiptDigest();failureReason=r.failureReason();createdAt=now;}UUID getId(){return id;}BrowserDevice getDevice(){return device;}String getActionType(){return actionType;}String getOutcome(){return outcome;}String getEvidenceSource(){return evidenceSource;}String getBeforeDigest(){return beforeDigest;}String getAfterDigest(){return afterDigest;}String getReceiptDigest(){return receiptDigest;}String getFailureReason(){return failureReason;}Instant getCreatedAt(){return createdAt;}}
